import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Create a Space","description":"Create, name, and scope a Space sensibly.","frontmatter":{"title":"Create a Space","description":"Create, name, and scope a Space sensibly."},"headers":[],"relativePath":"en/spaces/space-anlegen.md","filePath":"en/spaces/space-anlegen.md","lastUpdated":1788108473000}'),r={name:"en/spaces/space-anlegen.md"};function n(i,e,l,p,c,d){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="create-a-space" tabindex="-1">Create a Space <a class="header-anchor" href="#create-a-space" aria-label="Permalink to &quot;Create a Space&quot;">​</a></h1><p>A <strong>Space</strong> is the top-level organizational unit. It contains Grids, Pages, and Flows — and it&#39;s the unit that access rights, plan, and seats are tied to.</p><h2 id="creating-a-space" tabindex="-1">Creating a Space <a class="header-anchor" href="#creating-a-space" aria-label="Permalink to &quot;Creating a Space&quot;">​</a></h2><ol><li>Open the <strong>All Spaces</strong> overview.</li><li>Click <strong>Create new Space</strong>.</li><li>Give it a name.</li></ol><p>The dialog is titled <em>Create a Space</em>, with the prompt <em>Let&#39;s start with a name for your Space</em>.</p><p>If you don&#39;t have a Space yet, it reads <em>Create your first Space</em> instead.</p><p>Right after that, ApptiveGrid offers to create the first Grid: <em>Create Grid</em> — <em>Now choose a name for your first Grid</em>.</p><h2 id="how-to-scope-your-spaces" tabindex="-1">How to scope your Spaces <a class="header-anchor" href="#how-to-scope-your-spaces" aria-label="Permalink to &quot;How to scope your Spaces&quot;">​</a></h2><p>This is the most important decision, and changing it later takes real effort.</p><div class="warning custom-block"><p class="custom-block-title">A Space is the boundary for access and cost</p><p>Anyone with access to a Space sees <strong>everything</strong> in it, within the bounds of their <a href="/en/zusammenarbeit/rollen">Role</a>. There&#39;s no per-Grid permission.</p><p>The plan and <a href="/en/zusammenarbeit/sitzplaetze">seats</a> also apply per Space, not per account.</p></div><p>That gives you a rule of thumb:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Recommendation</th></tr></thead><tbody><tr><td>One team works on several topics</td><td><strong>One</strong> Space, multiple Grids</td></tr><tr><td>Different groups of people, separate data</td><td><strong>Multiple</strong> Spaces</td></tr><tr><td>Client data that clients shouldn&#39;t see from each other</td><td><strong>Multiple</strong> Spaces, or a <a href="/en/seiten/portal-veroeffentlichen">Portal</a> instead of an invitation</td></tr><tr><td>Personal data alongside general data</td><td><strong>A dedicated</strong> Space</td></tr><tr><td>Testing and playground</td><td><strong>A dedicated</strong> Space</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Don&#39;t split too hastily</p><p>Links between Grids only work <strong>within</strong> a Space. Things that belong together functionally should therefore live together — otherwise you won&#39;t be able to build links between them later.</p><p>So split by <em>access</em>, not by <em>topic</em>.</p></div><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Spaces can be assigned to a <strong>category</strong>. In the overview, <strong>Group by category</strong> bundles them accordingly; Spaces without one appear under <em>No category</em>.</p><div class="tip custom-block"><p class="custom-block-title">Around ten Spaces or more</p><p>With just a few Spaces, search (<em>Search Space…</em>) is enough. As the list grows, categories like &quot;Clients,&quot; &quot;Internal,&quot; &quot;Archive&quot; are the simplest way to stay organized.</p></div><h2 id="starting-with-a-template" tabindex="-1">Starting with a template <a class="header-anchor" href="#starting-with-a-template" aria-label="Permalink to &quot;Starting with a template&quot;">​</a></h2><p>Below the Space list is <em>Or start with a template</em>. A template creates a Space with ready-made Grids, Views, and in some cases Forms and Flows.</p><div class="tip custom-block"><p class="custom-block-title">Some templates need a higher plan</p><blockquote><p><em>This template requires at least a &quot;{plan}&quot; plan</em></p></blockquote><p>After the trial period ends, a template can become unusable: <em>You have completed the trial period for this template. To keep using this template, please upgrade to a higher plan.</em></p></div><p>→ <a href="/en/erste-schritte/vorlagen">Start with a template</a></p><h2 id="renaming-a-space" tabindex="-1">Renaming a Space <a class="header-anchor" href="#renaming-a-space" aria-label="Permalink to &quot;Renaming a Space&quot;">​</a></h2><p>Via <strong>Rename Space</strong> in the Space menu. The dialog asks: <em>Enter a new name for this Space.</em></p><div class="tip custom-block"><p class="custom-block-title">Renaming is uncritical</p><p>Grids, Views, Forms, Flows, and shared links keep working unchanged — nothing references them internally by name.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/spaces/symbol-und-farbe">Icon, color, and category</a></li><li><a href="/en/spaces/navigation">Set up navigation</a></li><li><a href="/en/spaces/einstellungen">Space settings</a></li><li><a href="/en/zusammenarbeit/personen-einladen">Invite people</a></li></ul>',25)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
